28	/// A [`Task`] is a future that has not yet started, and it is the job of
29	/// the [`super::Scheduler`] to make that happen, via [`super::Scheduler::dispatch`].
30	/// A task can either run on the main thread (in other words, the same thread as the
31	/// scheduler) or it can run in a background thread. The main difference between
32	/// the two is that background threads only have a read-only snapshot of the session,
33	/// while local tasks have exclusive access and can modify it as they please. Keep in mind that
34	/// local tasks will **block** the main event loop, so only use local tasks if you **need**
35	/// mutable state access or you need the absolute lowest latency possible.
36	#[must_use]
37	pub(in crate::server) enum Task {
38	    Background(BackgroundTaskBuilder),
39	    Sync(SyncTask),
40	}
