42	// The reason why this isn't just a 'static background closure
43	// is because we need to take a snapshot of the session before sending
44	// this task to the background, and the inner closure can't take the session
45	// as an immutable reference since it's used mutably elsewhere. So instead,
46	// a background task is built using an outer closure that borrows the session to take a snapshot,
47	// that the inner closure can capture. This builder closure has a lifetime linked to the scheduler.
48	// When the task is dispatched, the scheduler runs the synchronous builder, which takes the session
49	// as a reference, to create the inner 'static closure. That closure is then moved to a background task pool.
50	pub(in crate::server) struct BackgroundTaskBuilder {
51	    pub(super) schedule: BackgroundSchedule,
52	    pub(super) builder: BackgroundFnBuilder,
53	}
